<?php
require 'backend/auth.php'; require_login('admin'); require 'backend/db.php';
$csrf=token();
$search=trim($_GET['search']??'');
$edit=(int)($_GET['edit']??0);
$record=null;
if ($edit) { $stmt=$conn->prepare('SELECT * FROM events WHERE id=?'); $stmt->bind_param('i',$edit); $stmt->execute(); $record=$stmt->get_result()->fetch_assoc(); }
if ($search) { $like='%'.$search.'%'; $stmt=$conn->prepare('SELECT * FROM events WHERE name LIKE ? OR category LIKE ? ORDER BY id DESC'); $stmt->bind_param('ss',$like,$like); $stmt->execute(); $rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); }
else $rows=$conn->query('SELECT * FROM events ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);
?>
